require_once __DIR__.'/../includes/auth.php';requireRole('admin');
if(isPost()){verifyCsrf();$id=(int)($_POST['id']??0);$me=(int)currentUser()['id'];if($id===$me){flash('warning','لا يمكنك تغيير دور حسابك أو تعطيله من هنا.');redirect(url('admin/users.php'));}$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$target=$s->fetch();if($target){$role=$_POST['role']??$target['role'];$status=$_POST['status']??$target['status'];if(!in_array($role,['admin','editor','author'],true))$role=$target['role'];if(!in_array($status,['active','disabled'],true))$status=$target['status'];if($target['role']==='admin'&&$target['status']==='active'&&($role!=='admin'||$status!=='active')){$count=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'")->fetchColumn();if($count<=1){flash('danger','لا يمكن تعطيل أو تخفيض آخر مدير نشط.');redirect(url('admin/users.php'));}}db()->prepare('UPDATE users SET role=?,status=?,updated_at=NOW() WHERE id=?')->execute([$role,$status,$id]);flash('success','تم تحديث المستخدم.');}redirect(url('admin/users.php'));}
$q=trim($_GET['q']??'');$s=db()->prepare('SELECT id,name,email,role,status,created_at FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY created_at DESC');$s->execute(["%{$q}%","%{$q}%"]);$rows=$s->fetchAll();$pageTitle='المستخدمون';require __DIR__.'/includes/header.php';?><div class="card stat-card"><div class="card-body"><form class="mb-4"><input class="form-control" name="q" placeholder="بحث بالاسم أو البريد" value="<?=e($q)?>"></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>المستخدم</th><th>الدور</th><th>الحالة</th><th>تاريخ الانضمام</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small class="text-secondary"><?=e($r['email'])?></small></td><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><td><select class="form-select form-select-sm" name="role" <?=$r['id']==currentUser()['id']?'disabled':''?>><?php foreach(['admin'=>'مدير','editor'=>'محرر','author'=>'كاتب'] as $v=>$l):?><option value="<?=$v?>" <?=$r['role']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></td><td><select class="form-select form-select-sm" name="status" <?=$r['id']==currentUser()['id']?'disabled':''?>><option value="active" <?=$r['status']==='active'?'selected':''?>>نشط</option><option value="disabled" <?=$r['status']==='disabled'?'selected':''?>>معطّل</option></select></td><td><?=formatDate($r['created_at'])?></td><td><button class="btn btn-sm btn-primary" <?=$r['id']==currentUser()['id']?'disabled':''?>>حفظ</button></td></form></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/includes/footer.php';?>
